const trigger = $('Execute Workflow Trigger').first().json;
const query = (trigger.doctor_name || '').trim();

if (!query) {
  return [{ json: { success: false, found: false, matches: [], message: 'Please provide a doctor name to search for.' } }];
}

function normalize(s) {
  return (s || '')
    .toLowerCase()
    .replace(/\bdr\.?\b/g, '')
    .replace(/[^a-z\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const normalizedQuery = normalize(query);
const queryWords = normalizedQuery.split(' ').filter(Boolean);


function rowsFrom(nodeName) {
  const items = $(nodeName).all();
  const out = [];
  for (const item of items) {
    const j = item.json;
    if (Array.isArray(j)) {
      for (const row of j) out.push(row);
    } else if (j && typeof j === 'object') {
      // empty object / error body without id fields
      if (j.doctor_id || j.appointment_id || j.clinic_id) out.push(j);
      else if (Array.isArray(j.body)) {
        for (const row of j.body) out.push(row);
      }
    }
  }
  return out;
}

const doctors = rowsFrom('Get All Doctors').filter(d => d.doctor_id);

const matches = doctors.filter(d => {
  const normalizedName = normalize(d.doctor_name);
  const nameWords = normalizedName.split(' ').filter(Boolean);
  if (normalizedName === normalizedQuery) return true;
  if (normalizedName.includes(normalizedQuery) || normalizedQuery.includes(normalizedName)) return true;
  return queryWords.some(qw => nameWords.some(nw => nw === qw || nw.startsWith(qw) || qw.startsWith(nw)));
});

if (matches.length === 0) {
  return [{ json: { success: true, found: false, matches: [], message: 'No doctor found matching "' + query + '". Could you double-check the spelling, or share the specialty you need?' } }];
}

if (matches.length === 1) {
  const d = matches[0];
  return [{ json: { success: true, found: true, matches: [{ doctor_id: d.doctor_id, doctor_name: d.doctor_name, specialty: d.specialty }], message: 'Found ' + d.doctor_name + ' (' + (d.specialty || 'General') + ').' } }];
}

return [{ json: { success: true, found: true, matches: matches.map(d => ({ doctor_id: d.doctor_id, doctor_name: d.doctor_name, specialty: d.specialty })), message: 'Multiple doctors match "' + query + '": ' + matches.map(d => d.doctor_name).join(', ') + '. Ask the patient which one they mean before proceeding.' } }];
